/**
 * Typed client for same-origin `/api/*` endpoints.
 *
 * For use in Client Components that need to fetch after mount. It unwraps the
 * `{ data }` / `{ error }` envelope and throws `ApiClientError` on failure.
 * The browser must only ever call same-origin `/api/*` — never a third-party
 * API directly (that belongs in a route handler).
 */

interface ApiFailure {
  error: {
    code: string;
    message: string;
    issues?: { path: string; message: string }[];
  };
}

/** Thrown by `apiFetch` when an endpoint responds with an error envelope. */
export class ApiClientError extends Error {
  constructor(
    public readonly code: string,
    message: string,
    public readonly status: number,
  ) {
    super(message);
    this.name = "ApiClientError";
  }
}

/**
 * Calls a same-origin `/api` endpoint and returns the unwrapped `data`.
 * `path` must be a relative path (e.g. `/api/contact`).
 */
export async function apiFetch<T>(
  path: string,
  init?: RequestInit,
): Promise<T> {
  const res = await fetch(path, {
    ...init,
    headers: { "content-type": "application/json", ...init?.headers },
  });

  const body = (await res.json().catch(() => null)) as
    | { data: T }
    | ApiFailure
    | null;

  if (!res.ok || !body || "error" in body) {
    const err =
      body && "error" in body
        ? body.error
        : { code: "request_failed", message: "Request failed." };
    throw new ApiClientError(err.code, err.message, res.status);
  }

  return body.data;
}

/**
 * Shared helpers for `app/api/**` route handlers.
 *
 * Gives every endpoint a consistent JSON envelope and error handling:
 * - success → `{ data: ... }`
 * - failure → `{ error: { code, message, issues? } }`
 *
 * Route handlers stay free to hold business logic and secrets (the file is
 * server-only by construction) — these helpers only standardise the I/O shape.
 */

import { NextRequest, NextResponse } from "next/server";
import { ZodError } from "zod";

/** Throw inside a route handler to return a specific error response. */
export class ApiError extends Error {
  constructor(
    public readonly status: number,
    public readonly code: string,
    message: string,
  ) {
    super(message);
    this.name = "ApiError";
  }
}

type RouteContext = { params: Promise<Record<string, string>> };

/**
 * Wraps an `app/api` route handler. The handler returns its payload (wrapped
 * as `{ data }`, 200) or a `NextResponse` (passed through). Thrown errors are
 * mapped to the error envelope:
 * - `ZodError` / malformed JSON → 400
 * - `ApiError` → its own status/code
 * - anything else → 500 (logged server-side, no internals leaked)
 */
export function handle<C extends RouteContext = RouteContext>(
  handler: (req: NextRequest, ctx: C) => Promise<unknown>,
) {
  return async (req: NextRequest, ctx: C): Promise<NextResponse> => {
    try {
      const result = await handler(req, ctx);
      if (result instanceof NextResponse) return result;
      return NextResponse.json({ data: result }, { status: 200 });
    } catch (error) {
      if (error instanceof ZodError) {
        return NextResponse.json(
          {
            error: {
              code: "invalid_input",
              message: "Invalid request payload.",
              issues: error.issues.map((issue) => ({
                path: issue.path.map(String).join("."),
                message: issue.message,
              })),
            },
          },
          { status: 400 },
        );
      }
      if (error instanceof SyntaxError) {
        return NextResponse.json(
          { error: { code: "invalid_json", message: "Request body is not valid JSON." } },
          { status: 400 },
        );
      }
      if (error instanceof ApiError) {
        return NextResponse.json(
          { error: { code: error.code, message: error.message } },
          { status: error.status },
        );
      }
      console.error("[api] unhandled error:", error);
      return NextResponse.json(
        { error: { code: "internal_error", message: "Something went wrong." } },
        { status: 500 },
      );
    }
  };
}

import { z } from "zod";

import { getServerEnv } from "@/env";
import { ApiError, handle } from "@/lib/api";

/**
 * Example `app/api` endpoint — a contact / lead submission.
 *
 * Demonstrates the convention: the handler owns the work — it validates input,
 * reads a secret env var, and calls an upstream service inline. Secrets are
 * safe here because `route.ts` is never bundled to the browser.
 */

// Request schema — kept in the route since it isn't shared. Lift to a shared
// module only once another route needs it.
const contactSchema = z.object({
  name: z.string().min(1).max(100),
  email: z.email(),
  message: z.string().min(1).max(2000),
});

export const POST = handle(async (req) => {
  const input = contactSchema.parse(await req.json());

  const { CONTACT_ENDPOINT } = getServerEnv();

  if (CONTACT_ENDPOINT) {
    // Forward the lead to the configured upstream (CRM, webhook, …).
    const upstream = await fetch(CONTACT_ENDPOINT, {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify(input),
    });
    if (!upstream.ok) {
      throw new ApiError(502, "upstream_error", "Failed to deliver the message.");
    }
  } else {
    // No upstream configured — log server-side so the starter runs as-is.
    console.log("[api/contact] submission:", input);
  }

  return { received: true };
});

import type { NextConfig } from "next";

const nextConfig: NextConfig = {
  // Drop the `X-Powered-By: Next.js` response header.
  poweredByHeader: false,

  compiler: {
    // Strip `console.*` from production bundles, keeping error/warn for
    // monitoring. Left on in dev so logs stay available.
    removeConsole:
      process.env.NODE_ENV === "production"
        ? { exclude: ["error", "warn"] }
        : false,
  },

  images: {
    // Modern formats — smaller than JPEG/PNG; the browser picks what it supports.
    formats: ["image/avif", "image/webp"],
    // Breakpoints `next/image` uses to build `srcset`. `deviceSizes` covers
    // full-width images (aligned with the adaptive-grid breakpoints + retina);
    // `imageSizes` covers smaller, fixed-width images and icons.
    deviceSizes: [360, 640, 768, 1024, 1280, 1440, 1920, 2560],
    imageSizes: [16, 32, 48, 64, 96, 128, 256, 384],
  },

  // React Compiler (automatic memoisation) is an opt-in performance win.
  // It requires the `babel-plugin-react-compiler` dev dependency and routes
  // the build through Babel — enable once installed:
  // reactCompiler: true,
};

export default nextConfig;

